def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_def = 0
    opp_def = 0
    dc = 0
    cd = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
            if b == 'C':
                dc += 1
        if b == 'D':
            opp_def += 1
            if a == 'C':
                cd += 1

    my_last, opp_last = history[-1]

    if n == 99:
        return 'D'

    if dc >= 6 and cd <= 1:
        return 'D'

    if opp_last == 'D':
        if n >= 2 and history[-2][0] == 'D':
            if opp_def >= n * 0.5:
                return 'D'
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        if opp_def <= max(2, n // 10):
            return 'C'
        return 'D'

    if opp_last == 'C':
        if my_def == 0 and opp_def == 0 and n == 10:
            return 'D'
        if cd == 0:
            if dc >= 6:
                return 'D'
            if dc >= 3 and rng.random() < 0.8:
                return 'D'
            if dc >= 1 and rng.random() < 0.5:
                return 'D'
        return 'C'

    return 'C'
